const REPORT = { type: 'object', properties: { ok: { type: 'boolean' }, branch: { type: 'string' }, sha: { type: 'string' }, summary: { type: 'string' }, red_ids: { type: 'array', items: { type: 'string' } }, stop_reason: { type: 'string' }, parked: { type: 'array', items: { type: 'string' } } }, required: ['ok', 'branch', 'sha', 'summary'] }
const VERDICT = { type: 'object', properties: { pass: { type: 'boolean' }, blocking: { type: 'boolean' }, evidence: { type: 'string' } }, required: ['pass', 'evidence'] }
const PREFLIGHT = { type: 'object', properties: { pass: { type: 'boolean' }, blocking: { type: 'boolean' }, evidence: { type: 'string' }, e7_attached: { type: 'boolean' }, e1r_attached: { type: 'boolean' }, abi_base: { type: 'number' }, unlisted: { type: 'array', items: { type: 'string' } }, gaps: { type: 'array', items: { type: 'object', properties: { n: { type: 'number' }, still_open: { type: 'boolean' }, closed_by: { type: 'string' }, evidence: { type: 'string' } }, required: ['n', 'still_open'] } } }, required: ['pass', 'evidence', 'gaps', 'e7_attached', 'e1r_attached', 'abi_base'] }
